import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No suitable girl found")
        return

    idx = 0
    N = int(data[idx])
    M = int(data[idx + 1])
    idx += 2

    grid = []
    for i in range(N):
        row = list(map(int, data[idx:idx + M]))
        grid.append(row)
        idx += M

    # Find Rohit's house (1 at (1,1) in 1-indexed)
    rohit_r, rohit_c = -1, -1
    girls = []
    for r in range(N):
        for c in range(M):
            if grid[r][c] == 1:
                if r == 0 and c == 0:
                    rohit_r, rohit_c = r, c
                else:
                    girls.append((r, c))

    if rohit_r == -1 or rohit_c == -1:
        print("No suitable girl found")
        return

    # Count qualities for each girl (8 neighbors)
    # 1 represents a quality, count non-zero neighbors (max 8)
    # But 1 at (1,1) should not be considered as quality

    def count_qualities(r, c):
        count = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < M:
                    if (nr, nc) != (rohit_r, rohit_c):
                        if grid[nr][nc] == 1:
                            count += 1
        return count

    # Calculate distance using BFS
    def bfs_distance(start_r, start_c, end_r, end_c):
        if start_r == end_r and start_c == end_c:
            return 0

        visited = [[False] * M for _ in range(N)]
        queue = deque([(start_r, start_c, 0)])
        visited[start_r][start_c] = True

        while queue:
            r, c, dist = queue.popleft()

            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < M:
                        if nr == end_r and nc == end_c:
                            return dist + 1
                        if not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc, dist + 1))

        return float('inf')

    # Filter girls with at least one quality
    candidate_girls = []
    for r, c in girls:
        qualities = count_qualities(r, c)
        if qualities >= 1:
            dist = bfs_distance(rohit_r, rohit_c, r, c)
            candidate_girls.append((r, c, qualities, dist))

    if not candidate_girls:
        print("No suitable girl found")
        return

    if len(candidate_girls) == 1:
        r, c, q, d = candidate_girls[0]
        print(f"{r + 1}:{c + 1}:{q}")
        return

    # Check if any girl has maximum qualities
    max_qualities = max(g[2] for g in candidate_girls)
    max_qual_girls = [g for g in candidate_girls if g[2] == max_qualities]

    if len(max_qual_girls) > 1:
        # Check if all have same distance
        min_dist = min(g[3] for g in max_qual_girls)
        same_dist_girls = [g for g in max_qual_girls if g[3] == min_dist]

        if len(same_dist_girls) > 1:
            print("He's not interested in polygamy")
            return

    # Find the best candidate
    best = max_qual_girls[0]
    for g in max_qual_girls[1:]:
        if g[3] < best[3]:
            best = g

    r, c, q, d = best
    print(f"{r + 1}:{c + 1}:{q}")

if __name__ == "__main__":
    main()
